import {GameServicePlayerData} from "./types";
import {getDefaultPlayerData} from "./config";
import {IAdService, MockAdService, YandexAdService} from "../../common/ads";
import {
    allPromisesSettled,
    deepCopy,
    getErrorMessage,
    InstantDataService,
    LocalDataService,
    LocaleService,
    Observable,
    State,
    YandexDataService,
    YandexSdkWrapper
} from "../../common";
import {AdCooldownTracker} from "./utils/adCooldownTracker";
import {mergePlayerData} from "../../logic/mergePlayerData";
import {IGameConfig} from "../../logic";
import {setLocaleFromString} from "../../assets";
import {getCheatPlayerData} from "./cheats";
import {isMockAdEnabled} from "./mockGetters";
import {SimpleShopService} from '../shop/SimpleShopService';

/**
 * настройки и инжектинг рабочих сервисов
 * **/
export interface IGameServiceOptions {
    gameConfig: IGameConfig;
    /** опциональный логгинг в консоль **/
    isLogging?: boolean;
    /** опциональный key для сохранения данных **/
    playerDataKey?: string;
    /** моковые флаги для сторибука
     * чтобы не грузить его изменением урлов **/
    isMockShop?: boolean;
    isMockAd?: boolean;
}

/**
 * Общий фасад для
 * - сохранения данных и чтения
 * - включения рекламы
 * **/
export class GameService {
    private readonly playerDataState: State<GameServicePlayerData>;
    private readonly localDataService: InstantDataService;
    /** облачный сервис сохранения доступен только для авторизованных пользователей **/
    private cloudDataService: InstantDataService | undefined;
    private readonly playerDataKey: string;
    private readonly adCooldown: AdCooldownTracker;
    private adService?: IAdService;
    private readonly yandexSdkWrapper: YandexSdkWrapper;
    public shop?: SimpleShopService;
    private saveTimer?: number;
    protected lastSaveTimeMs?: number;
    private readonly gameConfig: IGameConfig;

    constructor(private readonly props: IGameServiceOptions) {
        this.gameConfig = props.gameConfig;

        const appId = this.gameConfig.gameId;
        this.playerDataKey = props.playerDataKey ?? `${appId}-playerData`;
        this.playerDataState = new State<GameServicePlayerData>(
            mergePlayerData(getDefaultPlayerData(this.gameConfig), undefined),
        );
        this.adCooldown = new AdCooldownTracker({
            ...this.gameConfig.ads.cooldowns,
        });
        this.yandexSdkWrapper = new YandexSdkWrapper({isLogging: props.isLogging});
        this.localDataService = new LocalDataService({
            appId,
        });
    }

    /****
     * Public
     ****/

    /** инициализация и загрузка - ставь в Boot scene preload **/
    async preload(): Promise<void> {
        /**
         * Добавляй сюда загрузки сервисов
         * ошибка загрузки не прервет остальные
         * благодаря allPromisesSettled (полифиллу Promise.allSettled)
         * **/
        const tasks = [
            {name: "localDataService", promise: this.localDataService.preload()},
            {name: "yandexSdk", promise: this.yandexSdkWrapper.init()},
        ].filter((task): task is { name: string; promise: Promise<void> } => !!task.promise);

        const results = await allPromisesSettled(tasks.map((t) => t.promise));

        results.forEach((r, index) => {
            if (r.status === "rejected") {
                this.warn(`${tasks[index].name} preload failed`, r.reason);
            }
        });

        await this.initCloudDataService();
        this.initAds();
        this.initLocale();
        try {
            /** надо убедиться что они не зависят друг от друга **/
            await allPromisesSettled([this.initShop(), this.readPlayerData()]);
        } catch (e) {
            console.warn(e);
        }
    }

    get isShopEnabled(): boolean {
        const hasBuyItems = this.shop?.isShopItemsEnabled() === true;
        const hasRewardItems = this.shop?.isRewardEnabled() === true;

        return hasBuyItems || hasRewardItems;
    }
    getGameConfig(): IGameConfig {
        return this.gameConfig;
    }

    get isFullAdEnabled(): boolean {
        return this.adService != null && this.adCooldown.canShowCommon();
    }

    get isRewardAdEnabled(): boolean {
        return this.adService != null && this.adCooldown.canShowReward();
    }

    /**
     * мгновенный доступ к данным игрока
     * внимание - используйте отдельные поля оттуда
     * не модифицируйте объект по ссылке
     *  **/
    getPlayerData(): GameServicePlayerData {
        /** deepCopy защищает вложенные массивы покупок от мутации по ссылке. **/
        return deepCopy(this.playerDataState.getState());
    }

    /**
     * Подписка на playerData только для чтения.
     *
     * Возвращает только Observable API и deepCopy значений, чтобы UI не мог
     * мутировать внутреннее состояние сервиса по ссылке.
     **/
    playerDataObservable(): Observable<GameServicePlayerData> {
        return {
            getState: () => deepCopy(this.playerDataState.getState()),
            on: (callback, keys) => this.playerDataState.on((playerData) => {
                callback(deepCopy(playerData));
            }, keys),
            once: (callback) => this.playerDataState.once((playerData) => {
                callback(deepCopy(playerData));
            }),
        };
    }

    /** синхронно обновляет данные игрока,
     * возможно вызовет сохранение
     * debounce частых сохранений - на стороне сервисов
     * **/
    setPlayerData(partial: Partial<GameServicePlayerData>): void {
        this.playerDataState.setState((playerData) => mergePlayerData(playerData, partial));
        this.log("playerData updated = ", this.playerDataState.getState());
        this.scheduleSave();
    }

    showCommonAd(onClose?: (args: { wasShown: boolean; error?: string }) => void): void {
        try {
            if (!this.adService) {
                onClose?.({wasShown: false, error: "adService not available"});
                return;
            }
            if (!this.isFullAdEnabled) {
                onClose?.({wasShown: false, error: "ad is not allowed yet"});
                return;
            }
            const mark = () => this.adCooldown.markCommon();
            this.adService.showCommonAd({
                onOpen: mark,
                onClose: (args) => {
                    if (args.wasShown) {
                        mark();
                    }
                    onClose?.(args);
                },
            });
        } catch (e) {
            onClose?.({wasShown: false, error: getErrorMessage(e)});
        }
    }

    showRewardedAd(
        onClose?: (args: { wasShown: boolean; error?: string; isReward: boolean }) => void,
    ): void {
        try {
            if (!this.adService || !this.isRewardAdEnabled) {
                onClose?.({wasShown: false, isReward: false, error: "ad not available"});
                return;
            }
            const mark = () => this.adCooldown.markReward();
            this.adService.showRewardedAd({
                onOpen: mark,
                onClose: (args) => {
                    if (args.wasShown) {
                        mark();
                    }
                    onClose?.(args);
                },
            });
        } catch (e) {
            onClose?.({wasShown: false, error: getErrorMessage(e), isReward: false});
        }
    }

    /****
     * Private
     ****/

    /** взять Player Data из дата сервисов,
     *  их get мгновеннен (читает из кэша)**/
    private async readPlayerData(): Promise<void> {
        try {
            const read = (service: InstantDataService | undefined) =>
                service?.getData<GameServicePlayerData>(this.playerDataKey);

            /** облачный сервис получает приоритет загрузки
             *  не надо писать что потеряются локальные данные - так и задумано
             *  если есть облачный сервис - сохранение идет через него
             *  мы не можем перезаписывать облачные данные локальными
             *  - это будет брешь и чит для юзеров
             * **/
            const primaryService = this.cloudDataService ?? this.localDataService;

            const defaultPlayerData = getDefaultPlayerData(this.gameConfig);
            const cheatPlayerData = getCheatPlayerData();
            const savedPlayerData = read(primaryService);
            const nextPlayerData = cheatPlayerData != null
                ? mergePlayerData(defaultPlayerData, cheatPlayerData)
                : this.getActualSavedPlayerData(savedPlayerData) ?? defaultPlayerData;
            this.playerDataState.setState(nextPlayerData);
        } catch (e) {
            this.warn(e);
        }
    }

    /** Принимает только актуальный формат сохранения: игра не вышла, легаси не мигрируем. **/
    private getActualSavedPlayerData(savedPlayerData: unknown): GameServicePlayerData | undefined {
        if (!isGameServicePlayerData(savedPlayerData)) {
            return;
        }

        return savedPlayerData;
    }

    private async initCloudDataService(): Promise<void> {
        const player = this.yandexSdkWrapper.getPlayer();
        if (!player) return;
        this.cloudDataService = new YandexDataService(player);
        try {
            await this.cloudDataService.preload();
        } catch (error) {
            this.warn("cloudDataService preload failed", error);
        }
    }

    private initAds(): void {
        if (this.adService != null) return;
        if (isMockAdEnabled() || this.props.isMockAd) {
            this.adService = new MockAdService();
        } else {
            const sdk = this.yandexSdkWrapper.getSDK();
            this.adService = sdk ? new YandexAdService(sdk) : undefined;
        }
        this.adCooldown.start();
    }

    private async initShop(): Promise<void> {
        if (this.shop != null) return;
        console.log('initShop 01');

        this.shop = new SimpleShopService({
            sdk: this.yandexSdkWrapper.getSDK(),
            isMockShop: this.props.isMockShop,
            showRewardedAd: () =>
                new Promise((resolve) => {
                    this.showRewardedAd((args) => resolve(args));
                }),
            playerDataService: this,
            adService: this.adService,
            isRewardAdEnable: () => this.isRewardAdEnabled,
            mapShopItemToPlayerData: this.gameConfig.shop.addShopItemToState,
            gameShopOrderedConfig: this.gameConfig.shop.shopItemsOrdered
        });
        await this.shop.preload();
    }

    private initLocale() {
        /** это очень простой сервис, мог бы быть функцией **/
        new LocaleService({
            sdk: this.yandexSdkWrapper.getSDK(),
            setLocaleFromString: setLocaleFromString,
        });
    }

    /****
     * Private logging
     ****/
    private log(...args: unknown[]) {
        if (!this.props.isLogging) return;
        console.log(...args);
    }

    // работает всегда
    private warn(...args: unknown[]) {
        console.warn(...args);
    }

    private scheduleSave() {
        const debounceMs = this.gameConfig.dataServiceOptions.saveDebounceMs;
        const now = Date.now();
        const lastSaveTimeMs = this.lastSaveTimeMs;

        if (lastSaveTimeMs == null || now - lastSaveTimeMs >= debounceMs) {
            if (this.saveTimer != null) {
                clearTimeout(this.saveTimer);
                this.saveTimer = undefined;
            }
            this.savePlayerData();
            return;
        }

        const safeDelayMs = Math.max(0, lastSaveTimeMs + debounceMs - now);
        if (this.saveTimer != null) {
            clearTimeout(this.saveTimer);
        }
        this.saveTimer = window.setTimeout(() => {
            this.saveTimer = undefined;
            this.savePlayerData();
        }, safeDelayMs);
    }

    private savePlayerData() {
        const playerData = this.playerDataState.getState();

        /** локальное сохранение - внутри try-catch  **/
        this.localDataService.setData(this.playerDataKey, playerData);
        /** облачное сохранение - внутри try-catch **/
        this.cloudDataService?.setData(this.playerDataKey, playerData);
        this.lastSaveTimeMs = Date.now();
    }
}

/** Проверяет, что сохранение соответствует текущей модели игрока без legacy-полей. */
function isGameServicePlayerData(value: unknown): value is GameServicePlayerData {
    if (!isRecord(value)) {
        return false;
    }

    if (hasLegacyPlayerDataFields(value)) {
        return false;
    }

    return typeof value.consumableUndo === "number"
        && typeof value.consumableHint === "number"
        && typeof value.consumableMagic === "number"
        && typeof value.isMusicOn === "boolean"
        && typeof value.isSoundOn === "boolean"
        && typeof value.locale === "string"
        && typeof value.spiderSuitsMode === "number"
        && typeof value.gameBgUrlOverlayOpacity === "number"
        && typeof value.cardsTheme === "string"
        && isOptionalString(value.cardBackAssetName)
        && isOptionalSpiderBackground(value.gameBackground);
}

/** Проверяет поля удаленной экономики, которые не принимаются в текущем формате сохранения. */
function hasLegacyPlayerDataFields(value: Record<string, unknown>): boolean {
    return "gold" in value
        || "boughtCardBackIds" in value
        || "boughtBackgroundIds" in value;
}

/** Проверяет, что значение является объектом с ключами. */
function isRecord(value: unknown): value is Record<string, unknown> {
    return typeof value === "object" && value != null;
}

/** Проверяет опциональное строковое поле. */
function isOptionalString(value: unknown): boolean {
    return value == null || typeof value === "string";
}

/** Проверяет опциональный фон игрока в текущем формате. */
function isOptionalSpiderBackground(value: unknown): boolean {
    if (value == null) {
        return true;
    }

    if (!isRecord(value)) {
        return false;
    }

    return typeof value.backgroundUrl === "string"
        && isOptionalString(value.backgroundUrlFallback);
}
