export function createViewStyleEntrance(scene: Phaser.Scene): Phaser.GameObjects.Container {
  const view = createContainerFromViewData(scene, viewStyleEntranceData);

  const uiDialogBgLightNine40 = createAssetChild(scene, viewStyleEntranceData.children['ui.dialog.bg.light.nine.40']);
  setLeftTop(
    uiDialogBgLightNine40,
    viewStyleEntranceData.children['ui.dialog.bg.light.nine.40'].x - viewStyleEntranceData.width / 2,
    viewStyleEntranceData.children['ui.dialog.bg.light.nine.40'].y - viewStyleEntranceData.height / 2,
  );
  view.add(uiDialogBgLightNine40);

  const buttonBack = createButtonBack(scene);
  setLeftTop(
    buttonBack,
    viewStyleEntranceData.children.buttonBack.x - viewStyleEntranceData.width / 2,
    viewStyleEntranceData.children.buttonBack.y - viewStyleEntranceData.height / 2,
  );
  view.add(buttonBack);

  const textViewStyleEntranceTitle = createTextChild(scene, viewStyleEntranceData.children.textViewStyleEntranceTitle);
  setLeftTop(
    textViewStyleEntranceTitle,
    viewStyleEntranceData.children.textViewStyleEntranceTitle.x - viewStyleEntranceData.width / 2,
    viewStyleEntranceData.children.textViewStyleEntranceTitle.y - viewStyleEntranceData.height / 2,
  );
  centerX(uiDialogBgLightNine40, textViewStyleEntranceTitle);
  view.add(textViewStyleEntranceTitle);

  const buttonStyleEntranceCardBacks = buildButtonStyleEntranceCardBacks(scene);
  setLeftTop(
    buttonStyleEntranceCardBacks,
    viewStyleEntranceData.children['button.StyleEntranceCardBacks'].x - viewStyleEntranceData.width / 2,
    viewStyleEntranceData.children['button.StyleEntranceCardBacks'].y - viewStyleEntranceData.height / 2,
  );
  view.add(buttonStyleEntranceCardBacks);

  const buttonStyleEntranceCards = buildButtonStyleEntranceCards(scene);
  setLeftTop(
    buttonStyleEntranceCards,
    viewStyleEntranceData.children['button.StyleEntranceCards'].x - viewStyleEntranceData.width / 2,
    viewStyleEntranceData.children['button.StyleEntranceCards'].y - viewStyleEntranceData.height / 2,
  );
  view.add(buttonStyleEntranceCards);

  const buttonStyleEntranceWallpapers = buildButtonStyleEntranceWallpapers(scene);
  setLeftTop(
    buttonStyleEntranceWallpapers,
    viewStyleEntranceData.children['button.StyleEntranceWallpapers'].x - viewStyleEntranceData.width / 2,
    viewStyleEntranceData.children['button.StyleEntranceWallpapers'].y - viewStyleEntranceData.height / 2,
  );
  view.add(buttonStyleEntranceWallpapers);

  return view;
}

