import {getPlayerConsumables, makePlayerConsumablesPatch} from "./logic/playerDataConsumables";
import {ConsumableAmounts, ConsumableType} from "./logic/shop/types";
import type {GamePlayerData, IShopConfig} from "./logic/types";

/** Идентификатор рекламного пакета бонусов внутри игрового магазина. **/
export const rewardBonusPurchaseId = "rewardBonus1";

const rewardItemIds = [
    rewardBonusPurchaseId
] as const;

/** Должны совпадать с id в API!!! **/
const buyItemIds = [
    'common', 'medium', 'big'
] as const;

export type InAppPurchaseId = typeof buyItemIds[number];
export type RewardPurchaseId = typeof rewardItemIds[number];
export type PurchaseId = InAppPurchaseId | RewardPurchaseId;

/** Сколько расходников начисляем за каждую покупку или rewarded-награду. **/
const shopItemConsumablesMap: Record<PurchaseId, ConsumableAmounts> = {
    [rewardBonusPurchaseId]: {
        [ConsumableType.UNDO]: 2,
        [ConsumableType.HINT]: 2,
        [ConsumableType.MAGIC]: 1,
    },
    common: {
        [ConsumableType.UNDO]: 5,
        [ConsumableType.HINT]: 5,
        [ConsumableType.MAGIC]: 2,
    },
    medium: {
        [ConsumableType.UNDO]: 12,
        [ConsumableType.HINT]: 12,
        [ConsumableType.MAGIC]: 5,
    },
    big: {
        [ConsumableType.UNDO]: 25,
        [ConsumableType.HINT]: 25,
        [ConsumableType.MAGIC]: 12,
    },
};

export const shopConfig: IShopConfig = {
    shopItemsOrdered: {
        rewardItemIds: [...rewardItemIds],
        buyItemIds: [...buyItemIds],
    },
    /** Конвертер id покупки в пакет расходных бонусов на балансе игрока. **/
    addShopItemToState: (shopItemId, prevPlayerData) => {
        const prev = prevPlayerData as GamePlayerData;
        if (!isShopItemId(shopItemId)) {
            throw new Error(`unknown shop item id: ${shopItemId}`);
        }

        const {consumables} = getShopItemData(shopItemId);
        const current = getPlayerConsumables(prev);

        return {
            ...prev,
            ...makePlayerConsumablesPatch({
                [ConsumableType.UNDO]: current[ConsumableType.UNDO] + consumables[ConsumableType.UNDO],
                [ConsumableType.HINT]: current[ConsumableType.HINT] + consumables[ConsumableType.HINT],
                [ConsumableType.MAGIC]: current[ConsumableType.MAGIC] + consumables[ConsumableType.MAGIC],
            }),
        }
    },
    getShopItemData
} as const;


/** Возвращает пакет бонусов для id магазина без передачи ссылки на конфиг. **/
function getShopItemData(shopItemId: string): { consumables: ConsumableAmounts } {
    const consumables = isShopItemId(shopItemId)
        ? shopItemConsumablesMap[shopItemId]
        : makeEmptyConsumables();

    return {
        consumables: {
            ...consumables,
        },
    };
}

/** Проверяет, что id есть в конфиге начисляемых пакетов бонусов. **/
function isShopItemId(shopItemId: string): shopItemId is PurchaseId {
    return shopItemId in shopItemConsumablesMap;
}

/** Создает пустой пакет для preview неизвестных id без общей ссылки на объект. **/
function makeEmptyConsumables(): ConsumableAmounts {
    return {
        [ConsumableType.UNDO]: 0,
        [ConsumableType.HINT]: 0,
        [ConsumableType.MAGIC]: 0,
    };
}
