import {autoAssetsConfig} from "../../../autoAssetsConfig";
import {
    createParticleEffectSetFromAtlasName,
    IStartParticleEffectPayload,
} from "../../../common";
import {SceneEvents} from "../../../common";

interface ISharedParticleEffectEvents {
    startParticleEffect: IStartParticleEffectPayload;
    stopParticleEffect: void;
}

/** Заказывает салют GameOver через общий слой ParticleEffectLayer. */
export function orderGameOverSalute(scene: Phaser.Scene): void {
    const particleEvents = new SceneEvents<ISharedParticleEffectEvents>({scene});
    particleEvents.emit("startParticleEffect", createGameOverProtonSaluteConfig(scene));
    particleEvents.unSubscribeAll();
}

/** Отправляет общему слою ParticleEffectLayer команду остановить все активные эмиттеры. */
export function stopGameOverSalute(scene: Phaser.Scene): void {
    const particleEvents = new SceneEvents<ISharedParticleEffectEvents>({scene});
    particleEvents.emit("stopParticleEffect");
    particleEvents.unSubscribeAll();
}

/** Собирает визуальные параметры GameOver-салюта в одном месте вне story. */
function createGameOverSaluteConfig(scene: Phaser.Scene): IStartParticleEffectPayload {
    const cannonIntervalMs = 2600;
    const cannonShotQuantity = 8;
    const cannonParticleLifespan = {min: 3400, max: 5200};
    const cannonParticleScale = {start: 0.29, end: 0.09};
    const cannonParticleRotate = {min: -22, max: 22};
    const cannonLeftAngle = {min: 262, max: 338};
    const cannonRightAngle = {min: 202, max: 262};
    const cannonPadding = 0.025;
    const cannonY = scene.scale.height * 0.4;

    return {
        particleSet: createParticleEffectSetFromAtlasName({
            scene,
            atlasName: "particles-cat-cheshires",
            atlases: autoAssetsConfig.preload.atlases,
        }),
        presetName: "cannonLeft",
        repeatIntervalMs: cannonIntervalMs,
        quantity: cannonShotQuantity,
        lifespan: cannonParticleLifespan,
        scale: cannonParticleScale,
        rotate: cannonParticleRotate,
        emitters: [
            {
                base: "cannonLeft",
                startDelayMs: 0,
                angle: cannonLeftAngle,
                origin: {
                    x: scene.scale.width * cannonPadding,
                    y: cannonY,
                },
            },
            {
                base: "cannonRight",
                startDelayMs: cannonIntervalMs / 2,
                angle: cannonRightAngle,
                origin: {
                    x: scene.scale.width * (1 - cannonPadding),
                    y: cannonY,
                },
            },
        ],
    };
}

/** Собирает Proton-подобный GameOver-салют отдельным конфигом, не меняя старый cannon-паттерн. */
function createGameOverProtonSaluteConfig(scene: Phaser.Scene): IStartParticleEffectPayload {
    return {
        particleSet: createParticleEffectSetFromAtlasName({
            scene,
            atlasName: "particles-cat-cheshires",
            atlases: autoAssetsConfig.preload.atlases,
        }),
        presetName: "protonFireworks",
        centerX: scene.scale.width / 2,
        width: scene.scale.width,
        origin: {
            x: 0,
            y: scene.scale.height + 24,
        },
        lifespan: {min: 2200, max: 3000},
        disableTint: true,
        cascadeOverrides: {
            rocketTrail: {
                disableTint: true,
            },
            denseBurst: {
                quantity: 12,
                disableTint: true,
            },
            softBurst: {
                quantity: 12,
                disableTint: true,
            },
        },
    };
}
