import {SceneEvents, SoundPlayer} from "../../../common";
import {GameServiceProvider} from '../../../services';
import {IGameConfig} from '../../../logic';
import {IGameEvents} from '../../events';
import {soundConfig} from '../../../config.sound';

interface IProps {
    scene: Phaser.Scene;
    gameConfig: IGameConfig;
}

const MUSIC_KEY = soundConfig.common.music;

/** todo 1 перенести на эвенты IGameScenes, убрать свои events.ts **/
export class SoundPlayerFeature {
    private readonly events: SceneEvents<IGameEvents>;
    private readonly soundPlayer: SoundPlayer;

    constructor(private readonly props: IProps) {
        const {scene} = props;
        this.soundPlayer = new SoundPlayer({scene});
        this.applyInitialSettings();

        this.events = new SceneEvents<IGameEvents>({scene});
        this.subscribedGameSounds();
    }

    private subscribedGameSounds() {
        const {scene, gameConfig} = this.props;
        this.events.on("gameSettingsUpdated", (settings) => {
            if (settings.isMusicOn) {
                this.soundPlayer.play({
                    soundKey: MUSIC_KEY,
                    volume: gameConfig.audio.musicVolume
                })
            } else {
                this.soundPlayer.stop({soundKey: soundConfig.common.music})
            }

            this.soundPlayer.setMuted({muted: !settings.isSoundOn});
        });

        this.events.on("playerCardsMoveStart", (data) => {
            const gameSoundConfig = soundConfig.playerMoveReactionSoundMap[data.type];
            if (gameSoundConfig == null) return;
            const {soundName, volume} = gameSoundConfig;
            scene.sound.play(soundName, {volume});
        });
        this.events.on("spiderGameWin", () => {
            scene.sound.play(soundConfig.common.fanfare, {volume: 0.5});
        });
        this.events.on("spiderStockDealCardPlace", () => {
            scene.sound.play(soundConfig.common.cardFlip, {volume: 1});
        });
        this.events.on("paidPurchaseSuccess", () => {
            scene.sound.play(soundConfig.common.purchaseSuccess, {volume: 0.75});
        });
    }

    private applyInitialSettings() {
        const {gameConfig} = this.props;
        const settings = GameServiceProvider.get().getPlayerData();
        if (settings.isMusicOn) {
            this.soundPlayer.play({soundKey: MUSIC_KEY, volume: gameConfig.audio.musicVolume})
        }
        this.soundPlayer.setMuted({muted: !settings.isSoundOn});
    }

    destroy(): void {
        this.events.unSubscribeAll();
        this.soundPlayer.destroy();
    }
}
