import { getLocalizedText } from "../../../../assets";
import type { Observable } from "../../../../common";
import type { ISpiderGameSceneViewState } from "../../logic/types";

interface IProps {
  scene: Phaser.Scene;
  gameState: Observable<ISpiderGameSceneViewState>;
}

const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
  fontFamily: "Russo One",
  fontSize: "24px",
  lineSpacing: 0,
  color: "#FFFFFF",
  stroke: "rgba(0, 0, 0, 0.65)",
  strokeThickness: 3,
};

export class SpiderCardInfo extends Phaser.GameObjects.Container {
  private readonly unSubs: Array<() => void> = [];
  private readonly label: Phaser.GameObjects.Text;

  constructor(private readonly props: IProps) {
    super(props.scene);
    const { scene, gameState } = props;

    this.label = new Phaser.GameObjects.Text(scene, 0, 0, "", textStyle);
    this.add(this.label);
    scene.add.existing(this);

    const applyState = (state: ISpiderGameSceneViewState) => {
      this.label.setText(
        getLocalizedText("spider.cardInfo", {
          dealCount: state.dealCount,
          undoCount: state.undoCount,
        }),
      );
    };

    this.unSubs.push(gameState.on(applyState, ["dealCount", "undoCount"]));
    applyState(gameState.getState());
  }

  destroy() {
    super.destroy();
    this.unSubs.forEach((u) => u());
    this.unSubs.length = 0;
  }
}
