import {ISceneDialogHandle, openSceneDialog} from "../../common/game-core";
import {SceneEvents} from "../../common";
import {gameConfig} from "../../config";
import {IGameEvents} from "../events";
import {ThemeShopDialogFlow} from "./theme-shop";

interface IProps {
    scene: Phaser.Scene;
}

export class SpiderSelectStyleDialogManager extends Phaser.GameObjects.Zone {
    private readonly unSubs: Array<() => void> = [];
    private dialog?: ISceneDialogHandle;

    constructor(private readonly props: IProps) {
        super(props.scene, 0, 0);
        const sceneEvents = new SceneEvents<IGameEvents>({scene: props.scene});
        this.unSubs.push(sceneEvents.on("onSelectStyleButtonClick", () => {
            this.openDialog();
        }));
        this.unSubs.push(() => this.dialog?.destroy());
    }

    destroy(fromScene?: boolean): void {
        this.unSubs.forEach((unSub) => unSub());
        this.unSubs.length = 0;
        this.dialog = undefined;
        super.destroy(fromScene);
    }

    openDialog(): void {
        const {scene} = this.props;
        const animationDuration = gameConfig.dialogs?.animationShowDuration ?? 180;

        this.dialog?.destroy();
        this.dialog = openSceneDialog({
            scene,
            animationDuration,
            isCloseOnOverlayClick: true,
            createContent: ({scene, close}) => {
                const flow = new ThemeShopDialogFlow({scene, close});
                return flow.view;
            },
            onClose: () => {
                this.dialog = undefined;
            },
        });
    }
}
