import { getSceneData } from "../../../common/context";
import { HtmlBackground } from "../../../common/html";

interface ISceneContext {
  backgroundUrl: string;
  backgroundUrlFallback?: string;
}

interface IProps {
  scene: Phaser.Scene;
}

/** @deprecated Use BgAssetManager instead. */
export class CustomBackground {
  private readonly htmlBg: HtmlBackground;

  constructor({ scene }: IProps) {

    const sceneContext = getSceneData<ISceneContext>({
      scene,
      key: "sceneContext",
    });

    this.htmlBg = new HtmlBackground({
      url: sceneContext?.backgroundUrl ?? "",
      fallbackUrl: sceneContext?.backgroundUrlFallback,
    });
  }

  reset(fromScene?: boolean) {
    this.htmlBg.destroy();
  }
}
