import {makeAlign} from "@kvisaz/phaser-sugar";
import {viewGameProgressBarData} from "../auto_generated/assets-views.view";

const BG_DATA = viewGameProgressBarData.children["progress.bg.gray.nine.8"];
const BAR_DATA = viewGameProgressBarData.children["progress.bar.greenlight.nine.8"];
const MAX_BAR_WIDTH = viewGameProgressBarData.width;

export class GameProgressBar extends Phaser.GameObjects.Container {
    private readonly bg: Phaser.GameObjects.NineSlice;
    private readonly bar: Phaser.GameObjects.NineSlice;

    constructor(scene: Phaser.Scene) {
        super(scene, 0, 0);

        this.bg = this.createBackground(scene);
        this.bar = this.createBar(scene);

        this.add([this.bg, this.bar]);
        this.setSize(viewGameProgressBarData.width, viewGameProgressBarData.height);
        this.setProgress(getGeneratedProgress());

        scene.add.existing(this);
    }

    setProgress(progress: number): void {
        const nextWidth = MAX_BAR_WIDTH * clampProgress(progress);
        this.bar.setSize(nextWidth, BAR_DATA.height);
        this.bar.setVisible(nextWidth > 0);
        makeAlign((align) => align.anchor(this.bg).leftIn(this.bar, 1).topIn(this.bar, 1));
    }

    private createBackground(scene: Phaser.Scene): Phaser.GameObjects.NineSlice {
        const padding = BG_DATA.asset.ninePadding ?? 8;
        const bg = scene.add.nineslice(
            0,
            0,
            BG_DATA.asset.url,
            BG_DATA.asset.frameName,
            BG_DATA.width,
            BG_DATA.height,
            padding,
            padding,
            padding,
            padding,
        );
        bg.name = BG_DATA.asset.name;
        return bg;
    }

    private createBar(scene: Phaser.Scene): Phaser.GameObjects.NineSlice {
        const padding = BAR_DATA.asset.ninePadding ?? 8;
        const bar = scene.add.nineslice(
            0,
            0,
            BAR_DATA.asset.url,
            BAR_DATA.asset.frameName,
            BAR_DATA.width,
            BAR_DATA.height,
            padding,
            padding,
            padding,
            padding,
        );
        bar.name = BAR_DATA.asset.name;
        return bar;
    }
}

function clampProgress(progress: number): number {
    return Math.max(0, Math.min(1, progress));
}

function getGeneratedProgress(): number {
    return BAR_DATA.width / viewGameProgressBarData.width;
}
