interface ICreateViewCardBackShopProps {
  scene: Phaser.Scene;
  cardBacks: ThemeCardBack[];
}

export function createViewCardBackShop(props: ICreateViewCardBackShopProps): Phaser.GameObjects.Container {
  const {scene, cardBacks} = props;
  const view = createContainerFromViewData(scene, viewCardBackShopData);

  const uiDialogBgLightNine40 = createAssetChild(scene, viewCardBackShopData.children['ui.dialog.bg.light.nine.40']);
  setLeftTop(
    uiDialogBgLightNine40,
    viewCardBackShopData.children['ui.dialog.bg.light.nine.40'].x - viewCardBackShopData.width / 2,
    viewCardBackShopData.children['ui.dialog.bg.light.nine.40'].y - viewCardBackShopData.height / 2,
  );
  view.add(uiDialogBgLightNine40);

  const textCardBackShopTitle = createTextChild(scene, viewCardBackShopData.children.TextCardBackShopTitle);
  setLeftTop(
    textCardBackShopTitle,
    viewCardBackShopData.children.TextCardBackShopTitle.x - viewCardBackShopData.width / 2,
    viewCardBackShopData.children.TextCardBackShopTitle.y - viewCardBackShopData.height / 2,
  );
  view.add(textCardBackShopTitle);

  centerX(uiDialogBgLightNine40, textCardBackShopTitle);


  const buttonBack = createButtonBack(scene);
  setLeftTop(
    buttonBack,
    viewCardBackShopData.children.buttonBack.x - viewCardBackShopData.width / 2,
    viewCardBackShopData.children.buttonBack.y - viewCardBackShopData.height / 2,
  );
  view.add(buttonBack);

  const cardBackShopContent = createCardBackShopContent({scene, cardBacks});
  makeAlign((align) => {
    align.anchor(uiDialogBgLightNine40).topIn(cardBackShopContent, 112).leftIn(cardBackShopContent, 72);
  });
  view.add(cardBackShopContent);

  return view;
}
