import {AlignMethod, layoutChain, makeAlign} from "@kvisaz/phaser-sugar";
import {createGO, Observable, SceneEvents} from "../../../../common";
import {ViewElementBuilder} from "../../../../assets";
import {ConsumableButton} from "../../../../assets/consumables";
import {ISpiderExposedState} from "../../../../common/games/spider";
import {
  ConsumableAmounts,
  ConsumableType,
  GamePlayerData,
  getPlayerConsumables,
  makePlayerConsumablesPatch,
} from "../../../../logic";
import {GameServiceProvider} from "../../../../services";
import {ISpiderUiEvents} from "./events";
import {gameScreenLayoutConfig} from "../../config.layout";

interface IProps {
  scene: Phaser.Scene;
  gameState: Observable<ISpiderExposedState>;
}

interface IConsumableButtons {
  undoButton: ConsumableButton;
  hintButton: ConsumableButton;
  magicButton: ConsumableButton;
}

type ConsumableActionEventName = "spiderUndoRequest" | "spiderHintRequest" | "spiderMagicRequest";

const CONSUMABLE_TYPE_BY_ACTION = {
  undo: ConsumableType.UNDO,
  hint: ConsumableType.HINT,
  magic: ConsumableType.MAGIC,
} as const;

const CONSUMABLE_PLAYER_DATA_KEYS: Array<keyof GamePlayerData> = [
  "consumableUndo",
  "consumableHint",
  "consumableMagic",
];

export class SpiderControls extends Phaser.GameObjects.Container {
  private readonly unSubs: Array<() => void> = [];
  private readonly sceneEvents: SceneEvents<ISpiderUiEvents>;
  private isRewardPurchaseInProgress = false;

  constructor(private readonly props: IProps) {
    super(props.scene);
    const { scene } = this.props;
    this.sceneEvents = new SceneEvents<ISpiderUiEvents>({ scene, autoUnSub: this });
    const buttons = this.createButtons();


    makeAlign(align => {
      const { left, top, gap } = gameScreenLayoutConfig.leftSidebar;

      const sidebar = layoutChain({
        children: buttons,
        alignToAnchor: AlignMethod.CENTER_X,
        alignToNext: AlignMethod.BOTTOM_TO,
        nextOffsetY: gap
      });
      align.anchorSceneScreen(scene).leftIn(sidebar, left).topIn(sidebar, top);
    })

    this.add(buttons);


    this.scene.add.existing(this);
  }

  destroy() {
    super.destroy();
    this.unSubs.forEach((u) => u());
    this.unSubs.length = 0;
  }

  private createButtons() {
    const { scene } = this.props;
    const { sceneEvents } = this;
    const builder = new ViewElementBuilder(scene);

    const newGameButton = createGO(() => builder.buttonNewGame(() => sceneEvents.emit("uiNewGameClick")));

    const replayButton = createGO(() => builder.buttonReplayGame(() => sceneEvents.emit("uiReplayClick")));

    const undoButton = createGO(() =>
      builder.buttonUndo(() => {
        this.handleConsumableClick(ConsumableType.UNDO, "spiderUndoRequest");
      }),
    );

    const hintButton = createGO(() =>
      builder.buttonHint(() => {
        this.handleConsumableClick(ConsumableType.HINT, "spiderHintRequest");
      }),
    );

    const magicButton = createGO(() =>
      builder.buttonMagic(() => {
        this.handleConsumableClick(ConsumableType.MAGIC, "spiderMagicRequest");
      }),
    );

    this.bindConsumableButtons({
      undoButton,
      hintButton,
      magicButton,
    });

    return [newGameButton, replayButton, undoButton, hintButton, magicButton];
  }

  /** Подписывает цифры кнопок бонусов на player data и совместимое scene-событие. */
  private bindConsumableButtons(buttons: IConsumableButtons): void {
    const playerDataObservable = GameServiceProvider.get().playerDataObservable();
    const syncConsumables = (playerData?: GamePlayerData) => {
      this.syncConsumableButtons(buttons, playerData ?? GameServiceProvider.get().getPlayerData());
    };

    syncConsumables(playerDataObservable.getState());
    this.unSubs.push(playerDataObservable.on(syncConsumables, CONSUMABLE_PLAYER_DATA_KEYS));
    this.unSubs.push(this.props.gameState.on(() => syncConsumables(), [
      "isUndoPossible",
      "isHintPossible",
      "isMagicPossible",
      "step",
    ]));
    this.unSubs.push(this.sceneEvents.on("gameConsumablesUpdated", () => syncConsumables()));
    this.unSubs.push(this.sceneEvents.on("gameRewardPurchaseClosed", ({ rewardItemId }) => {
      if (rewardItemId !== this.getRewardPurchaseId()) {
        return;
      }

      this.isRewardPurchaseInProgress = false;
      syncConsumables();
    }));
    this.unSubs.push(this.sceneEvents.on("spiderActionComplete", ({ action }) => {
      /** Расходник списываем здесь, а не по клику, потому что SpiderView мог отклонить request. */
      this.spendConsumable(CONSUMABLE_TYPE_BY_ACTION[action]);
    }));
  }

  /** Синхронизирует отображаемые числа с актуальным балансом расходников. */
  private syncConsumableButtons(buttons: IConsumableButtons, playerData: GamePlayerData): void {
    const consumables = getPlayerConsumables(playerData);
    const isRewardEnabled = this.canRequestReward();

    buttons.undoButton.setAmount(consumables[ConsumableType.UNDO]);
    buttons.hintButton.setAmount(consumables[ConsumableType.HINT]);
    buttons.magicButton.setAmount(consumables[ConsumableType.MAGIC]);

    buttons.undoButton.rewardIconEnable(isRewardEnabled);
    buttons.hintButton.rewardIconEnable(isRewardEnabled);
    buttons.magicButton.rewardIconEnable(isRewardEnabled);

    this.syncConsumableButtonEnabled(buttons, consumables);
  }

  /** Обновляет доступность кнопок с учетом обычного действия и rewarded-режима при нуле. */
  private syncConsumableButtonEnabled(buttons: IConsumableButtons, consumables: ConsumableAmounts): void {
    const gameState = this.props.gameState.getState();
    const canRequestReward = this.canRequestReward();

    buttons.undoButton.enable(
      this.canUseConsumable(consumables[ConsumableType.UNDO], gameState.isUndoPossible, canRequestReward),
    );
    buttons.hintButton.enable(
      this.canUseConsumable(
        consumables[ConsumableType.HINT],
        gameState.step === "idle" && gameState.isHintPossible,
        canRequestReward,
      ),
    );
    buttons.magicButton.enable(
      this.canUseConsumable(consumables[ConsumableType.MAGIC], gameState.isMagicPossible, canRequestReward),
    );
  }

  /** Проверяет, должна ли кнопка быть кликабельной для действия или rewarded-рекламы. */
  private canUseConsumable(amount: number, isActionPossible: boolean, isRewardEnabled: boolean): boolean {
    return amount > 0 ? isActionPossible : isRewardEnabled;
  }

  /** Выполняет бонусное действие или запускает rewarded-рекламу при нулевом балансе. */
  private handleConsumableClick(type: ConsumableType, eventName: ConsumableActionEventName): void {
    const gameService = GameServiceProvider.get();
    const consumables = getPlayerConsumables(gameService.getPlayerData());

    if (consumables[type] > 0) {
      this.sceneEvents.emit(eventName);
      return;
    }

    this.purchaseReward();
  }

  /** Списывает один выбранный бонус после успешного выполнения игрового действия. */
  private spendConsumable(type: ConsumableType): boolean {
    const gameService = GameServiceProvider.get();
    const consumables = getPlayerConsumables(gameService.getPlayerData());

    if (consumables[type] <= 0) {
      return false;
    }

    gameService.setPlayerData(makePlayerConsumablesPatch({
      ...consumables,
      [type]: consumables[type] - 1,
    }));

    return true;
  }

  /** Проверяет, можно ли запросить rewarded-пакет через тот же shop flow, что и в BonusShop. */
  private canRequestReward(): boolean {
    const gameService = GameServiceProvider.get();
    const rewardId = this.getRewardPurchaseId();

    return rewardId != null && gameService.shop?.isRewardEnabled() === true;
  }

  /** Возвращает первый configured reward id магазина бонусов. */
  private getRewardPurchaseId(): string | undefined {
    return GameServiceProvider.get().getGameConfig().shop.shopItemsOrdered.rewardItemIds[0];
  }

  /** Запрашивает rewarded-рекламу через общий overlay manager игровой сцены. */
  private purchaseReward(): void {
    if (this.isRewardPurchaseInProgress) {
      return;
    }

    const gameService = GameServiceProvider.get();
    const shop = gameService.shop;
    const rewardId = this.getRewardPurchaseId();
    if (shop == null || rewardId == null || !this.canRequestReward()) {
      return;
    }

    this.isRewardPurchaseInProgress = true;
    this.sceneEvents.emit("gameRewardPurchaseRequest", {
      rewardItemId: rewardId,
    });
  }
}
