import {BgAssetManager, SoundPlayerFeature} from "../shared";
import {SpiderGameScenes} from "../scenes";
import {SpiderAdOverlayManager} from "./ads";
import {SpiderGameSceneView} from "./SpiderGameSceneView";
import {
    BonusShopDialogManager,
    SpiderGameOverDialogManager,
    SpiderSelectStyleDialogManager,
    SpiderSettingsDialogManager
} from "../dialog";
import {addButtonInteractivity} from '../auto_generated/utils/addButtonViewInteractivity';
import {addGeneratedButtonSounds} from '../auto_tuned/utils.tuned';
import {gameConfig} from '../../config';
import {getCurrentLocale} from '../../assets';
import {ParticleEffectLayer, setSceneLocale} from '../../common';

export class SpiderGameScene extends Phaser.Scene {
    constructor() {
        super(SpiderGameScenes.SpiderGame);
    }

    preload() {
    }

    create() {
        const scene = this;
        setSceneLocale(scene, getCurrentLocale());

        addButtonInteractivity(scene);
        addGeneratedButtonSounds(scene);

        new BgAssetManager({scene, isColorOverlay: true});
        new SoundPlayerFeature({scene, gameConfig});
        new SpiderSettingsDialogManager({scene, gameConfig});
        new SpiderSelectStyleDialogManager({scene});
        new BonusShopDialogManager({scene, useRewardAdOverlay: true});
        new ParticleEffectLayer({scene});
        new SpiderGameOverDialogManager({scene});

        new SpiderAdOverlayManager({scene});
        new SpiderGameSceneView({scene});
    }
}
